class HarnessedAgent:
    def __init__(self, max_retries: int = 2) -> None:
        self.max_retries = max_retries
        self.command_history: list[str] = []

    def pre_execution_hook(self, command: str) -> None:
        for pattern in FORBIDDEN_PATTERNS:  # ['rm -rf', 'sudo', 'chmod 777', ...]
            if re.search(pattern, command):
                raise PermissionError(
                    f"BLOCKED BY PRE-HOOK: Dangerous command '{pattern}' detected."
                )

    def loop_detector(self, command: str) -> None:
        self.command_history.append(command)
        if len(self.command_history) >= self.max_retries:
            recent = self.command_history[-self.max_retries:]
            if len(set(recent)) == 1:
                raise RuntimeError(
                    f"BLOCKED BY HARNESS LOOP DETECTOR: Command '{command}' repeated "
                    f"{self.max_retries} times without progress."
                )

class CoreHarnessStack:
    def validate_tool_permission(self, tool_name: str, target_path: str = None) -> bool:
        allowed_tools = ["read_file", "write_file", "run_test", "list_dir"]
        if tool_name not in allowed_tools:
            self.log_event("PERMISSION_DENIED", {"reason": f"Tool '{tool_name}' not in allowed tool set."})
            return False

        if target_path:
            workspace = Path(self.workspace_root).resolve()
            abs_target = Path(target_path).resolve()
            if not abs_target.is_relative_to(workspace):
                self.log_event("PATH_TRAVERSAL_BLOCKED", {"path": str(abs_target), "workspace": str(workspace)})
                return False

        self.log_event("PERMISSION_GRANTED", {"tool": tool_name, "path": target_path})
        return True

    def run_post_edit_hook(self, file_path: str, code_content: str) -> bool:
        if "sk-proj-" in code_content:
            self.log_event("SECURITY_VIOLATION", {"file": file_path, "issue": "Hardcoded secret key!"})
            return False
        if not code_content.strip():
            self.log_event("QUALITY_VIOLATION", {"file": file_path, "issue": "Empty code edit proposal."})
            return False
        return True

class SpecVerifier:
    def attempt_write(self, target_file: str, code: str) -> tuple[bool, str]:
        relative = self._normalized(target_file)
        dest = (self.workspace / relative).resolve()

        if relative not in self.allowed_files or relative in self.forbidden_files:
            print(f"  [BLOCKED] SCOPE VIOLATION: '{relative}' outside allowed scope {self.allowed_files}.")
            return False, "SCOPE_VIOLATION"

        if not dest.is_relative_to(self.workspace.resolve()):
            print(f"  [BLOCKED] PATH VIOLATION: '{dest}' escapes workspace.")
            return False, "PATH_VIOLATION"

        lowered = code.lower()
        if "database" in lowered or "connect_db" in lowered or "oauth2" in lowered:
            print("  [BLOCKED] NON-GOAL VIOLATION: diff mentions database or OAuth2 refresh.")
            return False, "NON_GOAL_VIOLATION"

        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(code, encoding="utf-8")
        ast.parse(code, filename=str(dest))
        return True, str(dest)

class ClaudeCodeHookInterceptor:
    def intercept_pre_tool_use(self, tool_name: str, tool_input: dict) -> tuple[bool, str]:
        command = tool_input.get("command", "")
        if tool_name == "Bash":
            for flag in ["--dangerously-skip-permissions", "-y", "--force-all"]:
                if flag in command:
                    return False, f"CLI flag '{flag}' is prohibited by enterprise policy."
        return True, "PreToolUse check passed."

    @classmethod
    def permission_output(cls, decision: str, reason: str) -> dict:
        return {"hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": decision,  # allow | deny | ask | defer
            "permissionDecisionReason": reason,
        }}

class GuardrailsEngine:
    def audit_ast_and_secrets(self, file_path: str, code_content: str) -> tuple[bool, list[str]]:
        try:
            ast.parse(code_content, filename=file_path)
        except SyntaxError as exc:
            return False, [f"AST Syntax Error on line {exc.lineno}: {exc.msg}"]
        if re.search(r"(sk-proj-[A-Za-z0-9_\-]{20,}|AKIA[0-9A-Z]{16})", code_content):
            return False, ["SECURITY CRITICAL: Hardcoded API secret key detected!"]
        return True, ["AST syntax valid. Zero secret leaks detected."]

class PermissionEscalationGateway:
    def evaluate_request(self, tool_name: str, params: dict, request_id: str) -> dict:
        risk = self.risk_matrix.get(tool_name, "HIGH")
        if risk == "LOW":
            text = (self.workspace / params["path"]).read_text(encoding="utf-8")
            self._log({"event": "AUTO_APPROVED", "tool": tool_name, "path": params["path"]})
            return {"allowed": True, "content": text}
        if risk == "MEDIUM":
            (self.workspace / params["path"]).write_text(params["content"], encoding="utf-8")
            self._log({"event": "LOGGED_AND_APPROVED", "tool": tool_name, "path": params["path"]})
            return {"allowed": True, "path": str(self.workspace / params["path"])}
        if risk == "CRITICAL":
            approvals = self._approvals()
            if request_id not in approvals:
                self._log({"event": "ESCALATION_BLOCKED", "tool": tool_name, "request_id": request_id})
                return {"allowed": False, "reason": "missing_approval"}
            pending = {"request_id": request_id, "tool": tool_name, "approved_by": approvals[request_id]}
            (self.workspace / "pending_push.json").write_text(json.dumps(pending, indent=2), encoding="utf-8")
            self._log({"event": "CRITICAL_APPROVED_RECORDED", "tool": tool_name, "request_id": request_id})
            return {"allowed": True, "pending_push": str(self.workspace / "pending_push.json")}

class TDAReliabilityPipeline:
    def run_test_suite(self, code_under_test: str) -> dict:
        self.code_file.write_text(code_under_test, encoding="utf-8")
        result = subprocess.run(
            [sys.executable, "-m", "pytest", self.test_file.name, "-q", "--tb=short", "-p", "no:cacheprovider"],
            cwd=self.scratch_dir, capture_output=True, text=True, encoding="utf-8",
            env={**os.environ, "PYTHONDONTWRITEBYTECODE": "1"}
        )
        output = result.stdout + (result.stderr or "")
        summary = self._summary_line(output)
        if result.returncode != 0:
            return {"passed": False, "traceback": output, "returncode": result.returncode}
        return {"passed": True, "summary": summary}

    def format_fix_prompt(self, traceback_str: str) -> str:
        return f"System Instruction: Fix the following pytest failure output:\n```\n{traceback_str}\n```"

    def register_anti_regression_test(self, bug_name: str, test_code: str) -> dict:
        with self.test_file.open("a", encoding="utf-8") as handle:
            handle.write(f"\n\n{test_code.rstrip()}\n")
        return self.run_test_suite(self.code_file.read_text(encoding="utf-8"))

