class WorktreeIsolation:
    def add(self) -> Path:
        stamp = datetime.now(timezone.utc).strftime("%Y%m%d%H%M%S%f")
        self.branch = f"module08-agent-{os.getpid()}-{stamp}"
        self.path = Path(os.environ.get("TEMP", str(MODULE_DIR))) / self.branch
        subprocess.run(["git", "worktree", "add", "-b", self.branch, str(self.path), "HEAD"], cwd=self.repo_root)
        return self.path

    def remove(self) -> None:
        if self.path and self.branch:
            subprocess.run(["git", "worktree", "remove", "--force", str(self.path)], cwd=self.repo_root)
            subprocess.run(["git", "branch", "-D", self.branch], cwd=self.repo_root)

